"""Close source land-use labels while preserving pending physical gates."""
from . import geometry as g
from collections import Counter
OUT=g.HERE/'city_completion_ledger_r04'

def run():
 OUT.mkdir(exist_ok=True);prior=g.HERE/'city_completion_ledger_r03/completion_ledger.json';ledger=g.load(prior);mp=g.HERE/'backland_completion_r01/ground_margin_closure_r01/source_plan.json';margin=g.load(mp);ap=g.HERE/'backland_completion_r01/activation_patch_review_r05/acceptance.json';audit=g.load(ap);assert audit['passed']
 ledger['source_references'].update(prior_source_ledger=g.ref(prior),ground_margin_closure=g.ref(mp),independent_r05_surface_acceptance=g.ref(ap),author=g.ref(__file__))
 summary=ledger['summary'];summary.update(assigned_subthreshold_source_fragments=margin['summary']['small_fragments'],assigned_subthreshold_source_area_m2=2507,remaining_unlabelled_small_fragments=0,legacy_unimplemented_occupied_yard_claims_withdrawn=29,legacy_nonpublic_margin_source_area_m2=1046,unexplained_legacy_ground_access_obligations=0,legacy_source_access_links_still_requiring_final_composite_reconciliation=0)
 summary.pop('remaining_subthreshold_original_grid_area_m2',None)
 for r in ledger['blocks']:
  bid=r['block_id'];small=[x for x in margin['small_fragment_dispositions']if x['block_id']==bid];old=[x for x in margin['legacy_fragment_dispositions']if x['block_id']==bid]
  r.update(assigned_small_ground_margin_ids=[x['id']for x in small],assigned_small_ground_margin_area_m2=sum(x['source_area_m2']for x in small),small_margin_dispositions=dict(Counter(x['disposition']for x in small)),closed_legacy_margin_ids=[x['id']for x in old],closed_legacy_margin_area_m2=sum(x['source_area_m2']for x in old),unexplained_legacy_ground_access_obligations=0,unassigned_source_ground_area_m2=0)
  r['preserved_original_legacy_access_review_ids']=r.pop('legacy_source_access_review_ids');r.pop('subthreshold_original_grid_remnant_m2',None);r.pop('legacy_source_access_associated_area_m2',None)
 ledger['global_completion_gates']=[x for x in ledger['global_completion_gates']if not x.startswith('Reconcile legacy')]
 ledger['global_completion_gates'].insert(-1,'Preserve the exact ground-margin source dispositions: no occupied courtyard, productive garden or public spur is claimed on the 29 unactivated legacy fragments; any future change of use must reopen access design.')
 ledger['note']='BLOCK_009 is absent; BLOCK_012 is protected market. All original-grid residual land now has an explicit named disposition. This source land-use closure does not certify the pending 24 holdings/entries or final integrated traversal.'
 ledger['counting_policy']={'inherited_building_masses_703':'Planning-source inventory only; not a current building count.','diagnostic_native_instances_5055':'Native part/assembly instances in the parent diagnostic 61 scene; not a current building count.','source_ready_ordinary_holdings_87':'26 B15 and 61 other released whole holdings, each potentially containing multiple range or fixture assemblies.'}
 g.write(OUT/'completion_ledger.json',ledger)
 lines=['# Whole-city ordinary parcel completion ledger','', '87 ordinary holdings have matching source-ready native and terrain releases: 26 in B15 and 61 elsewhere. The remaining finite building/access queue is 17 private holdings plus seven B07 terraces. Final integrated support and traversal checks remain required.','', 'All residual source land has an explicit disposition. The 16 large patches cover 3,859 m²; the 869 smaller margins cover exactly 2,507 m². Current owners, public routes, measured slopes and existing support holes retain priority.','', 'The 29 legacy backland route-search failures cover 1,046 m² of unactivated fragments. None is in the 440 active material owners or the 835 native fixture selection. Their unimplemented generic courtyard/garden labels are superseded by nonpublic drainage and clearance margins. Fifteen adjacent owners have exact catalog roots; no root is substituted for a missing spur. There are no unexplained legacy courtyard-access obligations.','', 'Backland r05 independently passes: 76,988.978 m² of same-plane functional ground, 835 supported fixtures, 22 complete gated subyards, and 3,679.125 m² of native-hole union. No reserved-route paint or emitted top inside a native hole remains.','', 'Counting: the inherited 703 planning masses and the diagnostic scene’s 5,055 native part/assembly instances are different inventories. Neither is reported as the current number of buildings.','']
 for r in ledger['blocks']:
  lines += [f"## {r['block_id']}"]
  if r['block_id']=='BLOCK_012':lines+=['Protected market; no ordinary infill scope.',''];continue
  lines += [f"Holdings: {len(r['source_ready_B15_holdings'])+len(r['source_ready_private61_holdings'])} source-ready; {len(r['remaining_private17_holdings'])} private and {len(r['separate_B07_refit_holdings'])} B07 terrace holdings still pending.",f"Functional ground: {r['same_plane_material_area_m2']:,.1f} m²; {r['selected_backland_native_uses']} native uses; {len(r['complete_gated_subyard_ids'])} complete gated subyards."]
  if r['same_plane_ground_functions_m2']:lines+=['Uses: '+ '; '.join(k.replace('_',' ')for k,v in sorted(r['same_plane_ground_functions_m2'].items(),key=lambda x:-x[1]))+'.']
  if r['remaining_private17_holdings']:lines+=['Pending IDs: '+', '.join(x['id'].split(':')[-1]for x in r['remaining_private17_holdings'])+'.']
  lines += [f"Final large ground assignments: {len(r['new_residual_land_use_ids'])}, {r['new_residual_source_area_m2']:,.0f} m². Small road/terrain margins: {len(r['assigned_small_ground_margin_ids'])}, {r['assigned_small_ground_margin_area_m2']:,.0f} m². Legacy nonpublic margins: {len(r['closed_legacy_margin_ids'])}, {r['closed_legacy_margin_area_m2']:,.0f} m².",'Unlabeled source ground and unexplained legacy courtyard-access obligations: 0. Outer grounds remain intentionally open except for the explicitly complete gated subyards.','']
 lines+=['## Physical completion gates','',*['- '+x for x in ledger['global_completion_gates']]]
 (OUT/'completion_ledger.md').write_text('\n'.join(lines)+'\n');g.write(OUT/'manifest.json',dict(data=g.ref(OUT/'completion_ledger.json'),readable=g.ref(OUT/'completion_ledger.md'),summary=summary));print(g.ref(OUT/'completion_ledger.json'));print(g.ref(OUT/'completion_ledger.md'))

if __name__=='__main__':run()
